const evens = [];
for (let i = 0; i < 100; i++) { if (i % 2) evens.push({ x: i, y: 1 }); }
for (let i = 0; i < evens.length; i++) evens[i].y += evens[i].x;
const small = new __Vsc_small();
for (let i = 0; i < 40; i++) { if (i % 3 === 0) small.push(i); }
for (let i = 0; i < small.length; i++) small.x[i]++;
const both = [];
for (let i = 0; i < 50; i++) { if (i % 2) both.push({ x: i }); else both.push({ x: 0 }); }
for (let i = 0; i < both.length; i++) both[i].x *= 2;
const early = new __Vsc_early();
for (let i = 0; i < 80; i++) { if (i > 70) break; early.push(i); }
